source.jsLib:
var hosts = [
    "https://v1.vossc.com",
    "https://v2.vossc.com",
    "https://v3.vossc.com",
    "https://v4.vossc.com",
    "http://1.94.248.5:7001",
    "http://113.44.163.166:7001"
];

function getHosts() {
    return hosts;
}

function getServerHost() {
    let { source } = this;
    try {
        const config = JSON.parse(source.getVariable());
        return config?.[0]?.host || getHosts()[0];
    } catch (e) {
        return getHosts()[0];
    }
}

function getParagraphApiUrl() {
    let host = getServerHost.call(this);
    return host + '/para';
}

function deviceType() {
    let { java } = this;
    try {
        var id = java.deviceID();
        if (id && id !== '') {
            return true;
        }
    } catch (e) {}

    try {
        var id = java.androidId();
        if (id && id !== '') {
            return false;
        }
    } catch (e) {}

    return false;
}

function checkEnv() {
    let { java, source } = this;
    let isModified = false;
    try {
        new Packages.io.legato.kazusa.utils.TimeoutCancellationException('');
        isModified = true;
    } catch (e) {
        isModified = typeof source.loginUi == 'function' ? false : true;
    }

    return isModified;
}

function isQRead() {
    let { java } = this;
    try {
        return java.qread && java.qread() == "1";
    } catch (e) {
        return false;
    }
}

function getSecretKey() {
    let { java, source, cookie } = this;
    try {
        var headerValue = source.getLoginHeader();
        if (headerValue) {
            var headerStr = String(headerValue);
            if (headerStr && headerStr.length >= 10) {
                return java.base64Encode(headerStr);
            }
        }

        var cookieHeader = cookie.getCookie(getServerHost.call(this)) || '';
        var tokenMatch = cookieHeader.match(/X-Novel-Token=([^;]+)/);
        if (tokenMatch) {
            return tokenMatch[1];
        }

        java.toast("❌ 未登录，请先登录");
        return "";
    } catch (e) {
        java.toast("❌ 获取登陆状态失败");
        return "";
    }
}

function JJtoken() {
    let { java, source } = this;
    const config = getConfig.call(this);

    let key = '';

    try {
        const loginInfo = source.getLoginInfoMap() || {};
        key = loginInfo['晋江登录Token'] || '';
    } catch (e) {}

    if (!key) {
        key = config.jj_token || '';
    }

    if (!key) {
        java.toast("无法阅读未共享的章节和订阅付费章节");
    }
    return java.base64Encode(key);
}

function getConfig() {
    let { source } = this;
    try {
        let configStr = source.getVariable();
        if (!configStr || configStr.trim() === "") {
            return { host: getServerHost.call(this) };
        }
        let config = JSON.parse(configStr);
        if (!config || !Array.isArray(config) || config.length === 0) {
            return { host: getServerHost.call(this) };
        }
        return config[0] || { host: getServerHost.call(this) };
    } catch (e) {
        return { host: getServerHost.call(this) };
    }
}

function setConfig(key, value) {
    let { source } = this;
    try {
        let config = getConfig.call(this);
        config[key] = value;
        source.setVariable(JSON.stringify([config]));
        return true;
    } catch (e) {
        return false;
    }
}

function setConfigs(obj) {
    let { source } = this;
    try {
        let config = getConfig.call(this);
        for (let k in obj) {
            if (obj.hasOwnProperty(k)) {
                config[k] = obj[k];
            }
        }
        source.setVariable(JSON.stringify([config]));
        return true;
    } catch (e) {
        return false;
    }
}

function getSessionId() {
    const { cookie, source } = this;
    try {
        let cookieHeader = String(cookie.getCookie('fanqienovel.com'));
        let sessionId = cookieHeader.match(/sessionid=([^;]+)/)?.[1] || null;
        if (sessionId) {
            return sessionId;
        }
    } catch (e) {}
    try {
        let loginInfo = source.getLoginInfoMap() || {};
        return loginInfo['番茄登录Token'] || "";
    } catch (e) {
        return "";
    }
}

function splitArray(input, size) {
    let output = []
    for (let i = 0; i < input.length; i += size) {
        output.push(input.slice(i, i + size))
    }
    return output
}

function getCommentIconColor() {
    let {
        source
    } = this;
    let color = "#666666";
    let loginInfo = source.getLoginInfoMap() || "";
    if (loginInfo['段评图标颜色'] && loginInfo['段评图标颜色'].startsWith('#')) {
        color = loginInfo['段评图标颜色'];
    }
    return color;
}

function wrapContentForIOS(content) {
    if (content == null || content == undefined) {
        return '';
    }
    if (typeof content !== 'string') {
        try {
            content = String(content);
        } catch (e) {
            return '';
        }
    }
    const pureContent = content.trim();
    if (!deviceType.call(this)) {
        return pureContent;
    }
    let lines = pureContent.split('\n').map(line => {
        if (line && line.trim()) {
            const trimLine = line.trim().replace(/\s+/g, ' ');
            return `<div rs-native>${trimLine}</div>`;
        }
        return line || '';
    });
    return lines.join('\n');
}

function createCommentHtmlTag(displayText, url, sourceName) {
    url = url + (url.includes('?') ? '&' : '?') + 'key=' + getSecretKey.call(this);
    const encodedUrl = url.replace(/&/g, "&amp;").replace(/'/g, "\\'");
    return `<comment count="${displayText}" onPress="java.showReadingBrowser('${encodedUrl}','${sourceName}段评')">`;
}


function buildCommentUrl(sourceType, bid, cid, para) {
    let host = getServerHost.call(this);

    switch (sourceType) {
        case 'jj':
            return host + '/jj_comment?bid=' + bid + '&cid=' + cid + '&para=' + para;
        case 'qm':
            return host + '/qm_comment?item_id=' + cid + '&book_id=' + bid + '&paragraph_id=' + para;
        case 'qq':
            return host + '/qq_comment?bid=' + bid + '&cid=' + cid + '&para=' + para;
        case 'qd':
            return host + '/qd_comment?bid=' + bid + '&cid=' + cid + '&para=' + para;
        case 'fq':
        default:
            return host + '/idea_comment?item_id=' + cid + '&book_id=' + bid + '&para=' + para + '&sessionid=' + getSessionId.call(this);
    }
}

function getCommentSourceName(sourceType) {
    switch (sourceType) {
        case 'jj':
            return '晋江';
        case 'qm':
            return '七猫';
        case 'qq':
            return '企鹅';
        case 'qd':
            return '起点';
        case 'fq':
        default:
            return '番茄';
    }
}

function startCommentBrowser(url, title) {
    let { java, source } = this;

    let userHeight = source.getLoginInfoMap().get("📐段评高度%");
    let heightPercentage = 0.75; // 默认
    if (userHeight) {
        let h = parseFloat(userHeight);
        if (!isNaN(h)) {
            if (h > 1) h = h / 100;
            heightPercentage = Math.min(1, Math.max(0, h));
        }
    }

    let userRadius = source.getLoginInfoMap().get("📐段评圆角，填0-50之间");
    let cornerRadius = 20; // 默认20
    if (userRadius) {
        let r = parseInt(userRadius);
        if (!isNaN(r)) {
            cornerRadius = Math.min(50, Math.max(0, r)); // 限制在0-50之间
        }
    }

    if (isQRead.call(this)) {
        java.startBrowserDp(url, title);
    } else {
        let isModifiedVersion = checkEnv.call(this);
        if (isModifiedVersion) {
            try {
                let htmlContent = java.ajax(url);
                java.showBrowser(
                    url,
                    htmlContent,
                    `window.java=java;`,
                    JSON.stringify({
                        "expandedCornersRadius": cornerRadius,
                        "dismissOnTouchOutside": true,
                        "isDraggable": true,
                        "shouldDimBackground": true,
                        "backgroundDimAmount": 0.5,
                        "hardwareAccelerated": true,
                        "isNestedScrollingEnabled": true,
                        "isGestureInsetBottomIgnored": true,
                        "setFitToContents": false,
                        "heightPercentage": heightPercentage,
                        "isHideable": true
                    })
                );
            } catch (e) {
                java.showBrowser(
                    url,
                    null,
                    `window.java=java;`,
                    JSON.stringify({
                        "expandedCornersRadius": cornerRadius,
                        "dismissOnTouchOutside": true,
                        "hardwareAccelerated": true,
                        "isNestedScrollingEnabled": true,
                        "isGestureInsetBottomIgnored": true,
