function buildSearchResult(key, sourceParam, host) {
    let { java } = this;

    let fanqieMatch = null;
    if (key && typeof key === 'string') {
        fanqieMatch = key.match(/^(\d{19})@?(番茄小说|番茄听书|番茄漫画|番茄畅听|番茄短剧)?$/);
    }

    if (fanqieMatch) {
        let bookId = fanqieMatch[1];
        let inlineSource = fanqieMatch[2] || '';
        return handleFanqieSearch.call(this, bookId, host, inlineSource);
    } else if (key && key.length == 19 && !Number.isNaN(parseInt(key))) {
        return handleFanqieSearch.call(this, key, host, '');
    } else if (key && (key.length == 6 || key.length == 7 || key.length == 8) && !Number.isNaN(parseInt(key))) {
        return handleJjwxcSearch.call(this, key, host);
    } else {
        return host + '/search?login=search&key={{encodeURIComponent(key)}}&page={{page}}' + sourceParam;
    }
}

function handleFanqieSearch(key, host, inlineSource) {
    let { java } = this;

    var u = host + `/detail?book_id=${key}`;
    var kdy = java.base64Encode(u);
    var response = JSON.parse(java.ajax(u));
    var nam = response.data.book_name || (response.data[0] && response.data[0].book_name) || '未知';

    var validFanqieSources = ['番茄小说', '番茄听书', '番茄漫画', '番茄畅听', '番茄短剧'];

    var sourceName = '';

    if (inlineSource && validFanqieSources.indexOf(inlineSource) !== -1) {
        sourceName = inlineSource;
    }

    if (!sourceName) {
        try {
            var customSource = (source.getLoginInfoMap())['自定义源站'];
            if (customSource !== undefined && customSource !== null && String(customSource).trim() !== '') {
                var cs = String(customSource).trim();
                if (validFanqieSources.indexOf(cs) !== -1) {
                    sourceName = cs;
                }
            }
        } catch (e) {}
    }

    if (!sourceName) {
        var config = getConfig.call(this);
        var cfgSource = config && config.source;
        if (cfgSource && validFanqieSources.indexOf(cfgSource) !== -1) {
            sourceName = cfgSource;
        }
    }

    if (!sourceName) {
        sourceName = '番茄小说';
    }

    return host + `/details?url=${kdy}&source=${sourceName}&name=${encodeURIComponent(nam)}`;
}

function handleJjwxcSearch(key, host) {
    let { java } = this;
    var jjApiUrl = `http://app-cdn.jjwxc.net/androidapi/novelbasicinfo?novelId=${key}`;
    var jjResponse = java.ajax(jjApiUrl);
    var jjData = JSON.parse(jjResponse);
    var novelName = jjData.novelName || '未知';
    var encodedUrl = java.base64Encode(jjApiUrl);
    return host + `/details?url=${encodedUrl}&source=晋江&name=${encodeURIComponent(novelName)}`;
}

function syncFanqieShelf(isAdd) {
    let { java, book, source } = this;
    try {
        let syncStatus = java.get("book_sync") ?? "off";
        if (syncStatus != "on") return;
        if (!book || !book.tocUrl) return;

        let tocUrl = String(book.tocUrl);
        let base64Str = tocUrl.replace(/^data:catalogUrl;base64,/, '');
        let idx = base64Str.indexOf(',');
        if (idx >= 0) base64Str = base64Str.substring(0, idx);
        let catalog = JSON.parse(java.base64Decode(base64Str));

        if (!catalog) return;

        let fanqieSources = ["番茄小说", "番茄听书", "番茄畅听", "番茄漫画", "番茄短剧"];
        if (fanqieSources.indexOf(catalog.source) < 0) return;

        let bookId = String(catalog.bookid || "");
        if (!bookId) return;

        let sessionid = getSessionId.call(this);
        if (!sessionid) {
            java.toast("未获取到番茄登录状态，请先登录");
            return;
        }
        let cookie_ = 'sessionid=' + sessionid;

        if (isAdd) {
            java.toast("正在推送到番茄书架...");
            let res = java.ajax(
                "https://reading.snssdk.com/reading/bookapi/bookshelf/add/v?aid=1967," +
                JSON.stringify({
                    method: "POST",
                    headers: { "Cookie": cookie_ },
                    body: JSON.stringify({
                        add_book_source: 0,
                        identify_data: [{
                            asterisked: false,
                            book_id: bookId,
                            book_type: 0,
                            modify_time: 0
                        }]
                    })
                })
            );
            let data = JSON.parse(res);
            if (data.code == 0) {
                java.toast("推送成功");
            } else {
                java.toast("推送失败：" + (data.message || "未知错误"));
            }
        } else {
            java.toast("正在从番茄书架移除...");
            let res = java.ajax(
                "https://reading.snssdk.com/reading/bookapi/bookshelf/delete/v?aid=1967," +
                JSON.stringify({
                    method: "POST",
                    headers: { "Cookie": cookie_ },
                    body: JSON.stringify({
                        identify_data: [{
                            book_id: bookId,
                            book_type: 0,
                            modify_time: Date.now()
                        }]
                    })
                })
            );
            let data = JSON.parse(res);
            if (data.code == 0) {
                java.toast("移除成功");
            } else {
                java.toast("移除失败：" + (data.message || "未知错误"));
            }
        }
    } catch (e) {
        java.log("番茄书架同步失败: " + e);
        java.toast("番茄书架同步失败");
    }
}

function syncJjShelf(isAdd) {
    let { java, book } = this;
    try {
        if (!book || !book.tocUrl) return;

        let str = String(book.tocUrl);
        let b64 = str.replace(/^data:catalogUrl;base64,/, '');
        let idx = b64.indexOf(',');
        if (idx >= 0) b64 = b64.substring(0, idx);

        let catalog = JSON.parse(java.base64Decode(b64));
        if (!catalog) return;

        if (catalog.source != '晋江') return;

        let bookId = String(catalog.bookid || '');
        if (!bookId) {
            let m = String(catalog.url || '').match(/novelId=(\d+)/);
            if (m) bookId = m[1];
        }
        if (!bookId) {
            java.toast("无法获取晋江书籍ID");
            return;
        }

        let tokenB64 = JJtoken.call(this);
        if (!tokenB64) {
            java.toast("未配置晋江登录Token，无法同步书架");
            return;
        }

        let action = isAdd ? 'add' : 'del';
        let url = getServerHost.call(this) + '/jj_bookshelf?action=' + action 
                + '&book_id=' + bookId 
                + '&token=' + encodeURIComponent(tokenB64);

        if (isAdd) {
            let config = getConfig.call(this);
            let typeId = config.type_id || "0";
            url += '&type=' + typeId;
        }

        java.toast(isAdd ? "正在加入晋江书架..." : "正在从晋江书架移除...");

        let data = JSON.parse(java.ajax(url));

        if (data.code == "200" || data.code == 200) {
            let msg = data?.data?.list?.[0]?.message || data.message || (isAdd ? "加入成功" : "移除成功");
            java.toast(msg);
        } else {
            java.toast((isAdd ? "加入失败：" : "移除失败：") + (data.message || "未知错误"));
        }

    } catch (e) {
        java.log("晋江书架同步失败: " + e);
        java.toast("晋江书架同步失败");
    }
}

function encode(data) {
    let { java } = this;
    return java.createSymmetricCrypto("DES/CBC/PKCS5Padding", String("KW8Dvm2N"), String("1ae2c94b")).encryptBase64(data)
}

function decode(data) {
    let { java } = this;
    try {
        var encryptedBytes = java.base64DecodeToByteArray(data);
        var key = "G@tY3$jK7#mL2&pW8";
        var iv = "C!eH4&sM6@wP9^zX1";
        var crypto = java.createSymmetricCrypto("AES/CBC/PKCS5Padding", key, iv);
        return crypto.decryptStr(encryptedBytes);
    } catch (e) {
        return data;
    }
}

