function login(flag) {
    const host = getServerHost();

    if (flag == undefined) {
        const loginInfo = source.getLoginInfoMap();
        var email = loginInfo['邮箱'];
        var password = loginInfo['密码'];
    } else {
        source.putLoginInfo(JSON.stringify(result));
        var email = result['邮箱'];
        var password = result['密码'];
    }

    if (!email || !password) {
        java.toast("\n❌ 请先填写账号和密码并点击✓保存后登录");
        return;
    }

    java.toast("正在登录...");
    const url = host + '/login';
    const body = "email=" + encodeURIComponent(email) + "&password=" + encodeURIComponent(password);

    try {
        const response = java.ajax(url + "," + JSON.stringify({
            method: "POST",
            body: body,
            timeout: 10000
        }));

        const data = JSON.parse(response);

        if (data.code == 200) {
            const user = data.data.user;
            const deviceInfo = data.data.device || {};

            source.putLoginHeader(user.api_key);

            const nickname = user.nickname || "用户";
            const maskedEmail = email.includes('@') ? 
                email.substring(0, 3) + "****" + email.substring(email.indexOf('@')) : 
                email;
            const memberStatus = (user.is_member || false) ? "👑VIP会员" : "普通会员";
            const welcomeMsg = (user.is_member || false) ? "欢迎回来，👑尊贵VIP会员" : "欢迎回来";

            const onlineCount = deviceInfo.online_count || 0;
            const deviceLimit = deviceInfo.device_limit || 1;
            const totalCount = deviceInfo.total_count || 0;

            var deviceStatusText = "";
            if (onlineCount >= deviceLimit && totalCount > 0) {
                deviceStatusText = "⚠️ 设备已满（" + onlineCount + "/" + deviceLimit + "）\n新设备登录将挤掉旧设备";
            } else if (onlineCount > 0) {
                deviceStatusText = "📱 在线设备：" + onlineCount + "/" + deviceLimit;
            } else {
                deviceStatusText = "📱 当前无其他设备在线";
            }

            function maskDeviceId(deviceId) {
                if (!deviceId || deviceId.length <= 8) return deviceId || '未知';
                return deviceId.substring(0, 4) + "****" + deviceId.substring(deviceId.length - 4);
            }

            function maskIp(ip) {
                if (!ip) return '';
                if (ip.indexOf('.') !== -1 && ip.indexOf(':') == -1) {
                    var parts = ip.split('.');
                    if (parts.length == 4) return parts[0] + '.' + parts[1] + '.*.*';
                }
                if (ip.indexOf(':') !== -1) {
                    var parts = ip.split(':');
                    var validParts = [];
                    for (var i = 0; i < parts.length; i++) {
                        if (parts[i] !== '') validParts.push(parts[i]);
                    }
                    if (validParts.length >= 4) return validParts.slice(0, 4).join(':') + ':*:*';
                }
                return ip;
            }

