            let apiUrl = getServerHost() + '/audio_lrc?source=qm&book_id=' + bookId + '&item_id=' + itemId;
            let lrcData = java.ajax(apiUrl);
            result = decode(lrcData);
        }else{
            result='';
        }
    }catch(e){
        result='';
    }
}else{
    result='';
}

